const count = msg.payload || 1000;
const batchStart = Date.now();

// Reset all counters
const resetMsg = { payload: 'reset', _batch: { count: count, startTime: batchStart } };
node.send([null, null, resetMsg]);

// Generate messages with birth timestamps
for (let i = 0; i < count; i++) {
    node.send([{
        topic: 'tp/sensor',
        payload: 20 + Math.random() * 10,
        _birthTime: Date.now(),
        _seq: i
    }, null, null]);
}

const genElapsed = Date.now() - batchStart;
node.send([null, {
    payload: {
        stage: 'generator',
        messages: count,
        elapsed_ms: genElapsed,
        rate_per_sec: Math.round(count / (genElapsed / 1000))
    }
}, null]);

return null;

const ctx = context.get('state') || { count: 0, batch: null };

if (msg.payload === 'reset') {
    ctx.count = 0;
    ctx.batch = msg._batch;
    context.set('state', ctx);
    return null;
}

ctx.count++;

if (ctx.batch && ctx.count >= ctx.batch.count) {
    const elapsed = Date.now() - ctx.batch.startTime;
    const rate = Math.round(ctx.count / (elapsed / 1000));
    const report = {
        payload: {
            stage: 'event-in pass-thru (no calc)',
            messages: ctx.count,
            elapsed_ms: elapsed,
            rate_per_sec: rate
        }
    };
    ctx.count = 0;
    ctx.batch = null;
    context.set('state', ctx);
    return report;
}

context.set('state', ctx);
return null;

